/** Actual reader bake/content submissions under the independent released tray GL capture. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeScreenChipTrayChecks {
 private static final class Gallery extends net.minecraft.client.gui.screens.Screen {Gallery(){super(net.minecraft.network.chat.Component.literal("Integrated chip trays"));}@Override public void render(net.minecraft.client.gui.GuiGraphics graphics,int x,int y,float partial){}}
 private static NativeReaderRenderer.Bake bake;private static int frames,generation;private static boolean capture,done;private static final Object WORLD=new Object();private static final int LIGHT=0xA00070;private static int checks;
 private static boolean enabled(){return "true".equals(System.getenv("VANDOR_SCREEN_CHIP_TRAY_CHECK"));}
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Screen chip tray: "+why);}
 private static final class Collector implements VertexConsumer {final List<float[]> vertices=new ArrayList<>();float[] last;public VertexConsumer addVertex(float x,float y,float z){last=new float[]{x,y,z,Float.intBitsToFloat(-1)};vertices.add(last);return this;}public VertexConsumer setColor(int r,int g,int b,int a){last[3]=Float.intBitsToFloat(r|g<<8|b<<16|a<<24);return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){need((u|v<<16)==OverlayTexture.NO_OVERLAY,"explicit overlay");return this;}public VertexConsumer setUv2(int u,int v){need((u|v<<16)==LIGHT,"explicit packed light");return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static final VertexConsumer DISCARD=new VertexConsumer(){public VertexConsumer addVertex(float x,float y,float z){return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}};
 private static NativeTokenReader.Visual visual(int variant){return new NativeTokenReader.Visual(true,0,-1,false,variant==1?15:0,false);}
 private static void reference(){var mc=Minecraft.getInstance();int profiles=0;double error=0;try(var input=new java.util.zip.GZIPInputStream(new java.io.FileInputStream(System.getProperty("screenChipTrayReference")));var lines=new java.io.BufferedReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var family=ScreenFamily.fromId(row.get("id").getAsString());var state=family.decode(row.get("meta").getAsInt());var frame=ScreenChipMount.frame(family,state.facing,family==ScreenFamily.DIAGONAL?state.inverted:state.upper,row.get("ceiling").getAsBoolean(),row.get("position").getAsInt());int variant=row.get("variant").getAsInt();var collector=new Collector();NativeScreenChipTrayRenderer.renderAt(bake,frame,visual(variant),new NativeTokenReader.Motion(0,20,false,variant==2?12:0,0),20,variant==2,new PoseStack(),layer->collector,LIGHT,OverlayTexture.NO_OVERLAY);var expected=new ArrayList<float[]>();var pose=new Matrix4f();NativeScreenChipTrayRenderer.writePose(frame,pose);var gl=row.getAsJsonArray("draws").get(0).getAsJsonObject().getAsJsonArray("matrix");for(int c=0;c<4;c++)for(int r=0;r<4;r++)error=Math.max(error,Math.abs(pose.get(c,r)-Float.intBitsToFloat(gl.get(c*4+r).getAsInt())));
  for(var element:row.getAsJsonArray("draws")){var draw=element.getAsJsonObject();int stride=draw.get("stride").getAsInt()/4;var data=draw.getAsJsonArray("data");var matrix=draw.getAsJsonArray("matrix");for(int vertex=0;vertex<draw.get("vertices").getAsInt();vertex++){int at=vertex*stride;double x=Float.intBitsToFloat(data.get(at).getAsInt()),y=Float.intBitsToFloat(data.get(at+1).getAsInt()),z=Float.intBitsToFloat(data.get(at+2).getAsInt());float[] point=new float[4];for(int axis=0;axis<3;axis++)point[axis]=(float)(Float.intBitsToFloat(matrix.get(axis).getAsInt())*x+Float.intBitsToFloat(matrix.get(4+axis).getAsInt())*y+Float.intBitsToFloat(matrix.get(8+axis).getAsInt())*z+Float.intBitsToFloat(matrix.get(12+axis).getAsInt()));point[3]=Float.intBitsToFloat(data.get(at+3).getAsInt());expected.add(point);}}
  need(expected.size()==collector.vertices.size(),"actual Source model/overlay vertex count profile="+profiles+" Source="+expected.size()+" native="+collector.vertices.size());boolean[] matched=new boolean[expected.size()];for(var actual:collector.vertices){int found=-1;for(int i=0;i<expected.size();i++){if(matched[i])continue;var old=expected.get(i);if(Math.abs(actual[0]-old[0])<2e-6&&Math.abs(actual[1]-old[1])<2e-6&&Math.abs(actual[2]-old[2])<2e-6&&Float.floatToRawIntBits(actual[3])==Float.floatToRawIntBits(old[3])){found=i;break;}}need(found>=0,"Source posed authored model/overlay position+color profile="+profiles+" point="+Arrays.toString(actual));matched[found]=true;}profiles++;}}catch(Exception failure){throw new IllegalStateException("Tray actual Source capture",failure);}need(profiles==576&&error<2e-6,"complete Source poses and exact affine error="+error);clock();System.out.println("[vandorlabs][screen-chip-tray] reference PASS profiles="+profiles+" checks="+checks+" maxMatrixError="+error);}
 private static void clock(){var p=new BlockPos(9,80,-5);var visual=new NativeTokenReader.Visual(true,0,0,true,15,true);var a=new NativeTokenReader.Motion(7,6,false,0,0);var first=NativeReaderVisualClock.sampleAt(WORLD,p,2,visual,a,100);need(first.age()==6,"loaded mid-insertion starts at observed age");var repeated=NativeReaderVisualClock.sampleAt(WORLD,p,2,visual,new NativeTokenReader.Motion(7,0,false,0,0),102);need(repeated==first&&repeated.age()==8,"repeat/replacement sameworldposition doesnotrestart");need(NativeReaderVisualClock.sampleAt(WORLD,p,2,visual,a,102).age()==8,"paused timestamp holds");need(NativeReaderVisualClock.sampleAt(WORLD,p,2,visual,new NativeTokenReader.Motion(8,0,false,0,0),103).age()==0,"new insertion sequence restarts");need(NativeReaderVisualClock.sampleAt(new Object(),p,2,visual,a,100).age()==6,"world identity isolated");var pause=new com.vandorlabs.animation.VisualClock();need(pause.sample(0,false)==0&&pause.sample(50000000,false)==1&&pause.sample(100000000,true)==1&&pause.sample(1000000000,true)==1&&pause.sample(1050000000,false)==1&&pause.sample(1100000000,false)==2,"shared pause/resume clock");NativeReaderVisualClock.clear(WORLD);}
 private static void prepare(){var mc=Minecraft.getInstance();bake=new NativeReaderRenderer.Bake(id->mc.getModelManager().getModel(ModelResourceLocation.standalone(ResourceLocation.parse(id))));reference();var frame=ScreenChipMount.frame(ScreenFamily.CONSOLE,2,false,false,1);var poses=new PoseStack();var visual=visual(0);var motion=new NativeTokenReader.Motion(0,20,false,0,0);MultiBufferSource buffers=layer->DISCARD;for(int i=0;i<12000;i++){NativeScreenChipTrayRenderer.renderAt(bake,frame,visual,motion,20,false,poses,buffers,LIGHT,OverlayTexture.NO_OVERLAY);NativeScreenChipTrayRenderer.render(bake,frame,visual,motion,WORLD,BlockPos.ZERO,poses,buffers,LIGHT,OverlayTexture.NO_OVERLAY);}var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(id);for(int i=0;i<10000;i++){NativeScreenChipTrayRenderer.renderAt(bake,frame,visual,motion,20,false,poses,buffers,LIGHT,OverlayTexture.NO_OVERLAY);NativeScreenChipTrayRenderer.render(bake,frame,visual,motion,WORLD,BlockPos.ZERO,poses,buffers,LIGHT,OverlayTexture.NO_OVERLAY);}long bytes=meter.getThreadAllocatedBytes(id)-before;need(bytes<=1024,"warm10000 draws allocated="+bytes);System.out.println("[vandorlabs][screen-chip-tray] warm PASS generation="+generation+" allocated="+bytes+" retained="+NativeScreenChipTrayRenderer.retainedBytes());}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!enabled()||done||Minecraft.getInstance().getOverlay()!=null)return;var mc=Minecraft.getInstance();if(event.getScreen() instanceof TitleScreen){mc.setScreen(new Gallery());return;}if(!(event.getScreen() instanceof Gallery))return;if(bake==null)prepare();var gui=event.getGuiGraphics();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);var buffers=mc.renderBuffers().bufferSource();if(frames>=4)for(int i=0;i<12;i++){var family=new ScreenFamily[]{ScreenFamily.CONSOLE,ScreenFamily.HALF_CONSOLE,ScreenFamily.DIAGONAL,ScreenFamily.HALF_DIAGONAL}[i/3];var frame=ScreenChipMount.frame(family,2,i/3==3,false,1);var matrix=new Matrix4f();NativeScreenChipTrayRenderer.writePose(frame,matrix);var poses=gui.pose();poses.pushPose();try{poses.translate(80+i%4*150,50+i/4*110,300);poses.scale(90,-90,-90);poses.translate(-.5,-.5,0);poses.mulPose(matrix.invert());var visual=new NativeTokenReader.Visual(true,1,i%3==0?1:-1,i%3==2,i%3==2?15:0,i%3==2);var motion=new NativeTokenReader.Motion(i,16,false,i%3==1?12:0,0);NativeScreenChipTrayRenderer.renderAt(bake,frame,visual,motion,16,i%3==1,poses,buffers,0xF000F0,OverlayTexture.NO_OVERLAY);}finally{poses.popPose();}buffers.endBatch();gui.flush();}frames++;capture=frames==4||frames==9;}
 @SubscribeEvent public static void captured(RenderFrameEvent.Post event)throws Exception{if(!capture||done)return;capture=false;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){var path=mc.gameDirectory.toPath().resolve("screenshots/tray-"+generation+"-"+(frames==4?"disabled":"positive")+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);double scale=mc.getWindow().getGuiScale();for(int i=0;i<12;i++){int count=0,orange=0,cyan=0;for(int y=0;y<90*scale;y++)for(int x=0;x<140*scale;x++){int px=(int)((10+i%4*150)*scale)+x,py=(int)((5+i/4*110)*scale)+y;int rgb=image.getPixelRGBA(px,py)&0xffffff;if(rgb!=0x302820)count++;int r=rgb&255,g=(rgb>>8)&255,b=rgb>>16;if(r>180&&g>80&&g<220&&b<120)orange++;if(r<160&&g>180&&b>180)cyan++;}need(frames==4?count==0:count>100,"actual tray scene="+i+" generation="+generation+" ink="+count);if(frames==9&&i%3==1)need(orange>100,"actual rejection X visible scene="+i+" orange="+orange);if(frames==9&&i%3==2)need(cyan>10,"actual occupied active indicator visible scene="+i+" cyan="+cyan);}if(frames==9){if(generation++==0){bake=null;frames=0;mc.reloadResourcePacks();}else{done=true;System.out.println("[vandorlabs][screen-chip-tray] title PASS 12scenes/frame+logo+reject+credential/reload/disablednegative");mc.stop();}}}}
}
